pub(crate) fn bounds_report_line(source: &str, at: i64) -> i64 {
    let end = at.min(source.len() as i64);
    nikaia_std::index::get(&source.as_bytes(), nikaia_std::index::at(0..end)).iter().copied().filter(|&b| { b == 10 }).count() as i64 + 1
}

